<?php /** The policy form for a library or a folder. Data: target {kind, id, name, own_policy, effective, estimate, path, is_root}, admin */ $t = $target; $e = $t['estimate']; $cur = $t['own_policy'] ?? ($t['kind'] === 'folder' ? 'inherit' : 'index'); ?>
<div class="card mb-3" id="graph-policy-card"><div class="card-header"><h6 class="m-0">The graph policy of <?= e($t['kind'] === 'folder' ? $t['path'] : $t['name']) ?></h6></div>
    <div class="card-body">
        <div class="fs-12 text-muted mb-2">In effect now: <span class="badge bg-soft-<?= e(GRAPH_POLICY_BADGE[$t['effective']] ?? 'secondary') ?>" id="graph-policy-effective"><?= e($t['effective']) ?></span><?php if ($t['kind'] === 'folder' && ($t['own_policy'] ?? null) === null): ?> (inherited)<?php endif; ?></div>
        <form method="post" action="/graph/policy.php" hx-post="/graph/policy.php" hx-target="#flash" id="graph-policy-form"><?= csrf_field() ?>
            <input type="hidden" name="<?= $t['kind'] === 'folder' ? 'folder' : 'library' ?>" value="<?= (int) $t['id'] ?>"><input type="hidden" name="return_to" value="/graph/admin?<?= $t['kind'] ?>=<?= (int) $t['id'] ?>">
            <?php $opts = GRAPH_POLICIES; if ($t['kind'] === 'folder' && !$t['is_root']) { $opts = ['inherit' => 'Inherit — the folder above decides'] + $opts; } ?>
            <?php foreach ($opts as $k => $label): ?><div class="form-check mb-1"><input class="form-check-input" type="radio" name="graph_policy" id="graph-policy-<?= e($k) ?>" value="<?= e($k) ?>"<?= $cur === $k ? ' checked' : '' ?><?= $k === 'full' && !$admin ? ' disabled' : '' ?>><label class="form-check-label fs-12" for="graph-policy-<?= e($k) ?>"><?= e($label) ?><?= $k === 'full' && !$admin ? ' (the graph admin\'s)' : '' ?></label></div><?php endforeach; ?>
            <div class="alert alert-light fs-12 mt-2 mb-2" id="graph-estimate"><i class="feather-info me-1"></i>A <em>full</em> policy now: <?= e(estimate_sentence($e)) ?><?php if (!$e['engine_available']): ?> The engine is unavailable: the queue will wait.<?php endif; ?></div>
            <?php if ($e['over_budget'] && $admin): ?><div class="mb-2"><label class="form-label fs-12" for="graph-policy-confirm">Over budget — type <code>full</code> to confirm a full policy</label><input type="text" name="confirm" id="graph-policy-confirm" class="form-control btn-touch" style="max-width:200px" autocomplete="off"></div><?php endif; ?>
            <button type="submit" class="btn btn-primary btn-touch" id="graph-policy-save">Set the policy</button>
        </form>
        <?php if ($admin): ?><form method="post" action="/graph/rebuild.php" hx-post="/graph/rebuild.php" hx-target="#flash" hx-confirm="Re-send every document under it to the graph? A full library may cost the month's budget." class="mt-3" id="graph-rebuild-form"><?= csrf_field() ?><input type="hidden" name="<?= $t['kind'] === 'folder' ? 'folder' : 'library' ?>" value="<?= (int) $t['id'] ?>"><input type="hidden" name="confirm" value="yes"><button type="submit" class="btn btn-light btn-touch" id="graph-rebuild-btn"><i class="feather-refresh-cw me-1"></i>Rebuild: re-send everything under it</button></form><?php endif; ?>
    </div></div>
